import { createFileRoute, Link } from "@tanstack/react-router";
import { useEffect, useMemo, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { SiteHeader } from "@/components/SiteHeader";
import { Certificate } from "@/components/Certificate";

export const Route = createFileRoute("/gallery")({
  head: () => ({
    meta: [
      { title: "Certificate Gallery | 10 Minute School" },
      {
        name: "description",
        content:
          "Browse every result certificate generated by 10 Minute School students. Filter by class or search by student and school name.",
      },
      { property: "og:title", content: "Certificate Gallery | 10 Minute School" },
      {
        property: "og:description",
        content:
          "Browse all student result certificates. Filter by class, search by name or school.",
      },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary_large_image" },
    ],
  }),
  component: GalleryPage,
});

const CLASS_FILTERS = ["All", "Class 6", "Class 7", "Class 8", "Class 9", "Class 10"];

type Row = {
  id: string;
  certificate_name: string;
  school_name: string;
  exam_name: string;
  class_name: string | null;
  class_position: number;
  total_marks: number;
  created_at: string;
};

const MOCK_ROWS: Row[] = [
  {
    id: "sample-1",
    certificate_name: "আরিফ হোসেন",
    school_name: "ঢাকা রেসিডেন্সিয়াল মডেল কলেজ",
    exam_name: "বার্ষিক পরীক্ষা ২০২৫",
    class_name: "Class 10",
    class_position: 1,
    total_marks: 95,
    created_at: new Date().toISOString(),
  },
  {
    id: "sample-2",
    certificate_name: "নাসরিন আক্তার",
    school_name: "ভিকারুননিসা নূন স্কুল অ্যান্ড কলেজ",
    exam_name: "অর্ধবার্ষিক পরীক্ষা ২০২৫",
    class_name: "Class 9",
    class_position: 2,
    total_marks: 92,
    created_at: new Date().toISOString(),
  },
  {
    id: "sample-3",
    certificate_name: "তানভীর আহমেদ",
    school_name: "নটর ডেম কলেজ (হাই স্কুল)",
    exam_name: "মডেল টেস্ট ২০২৫",
    class_name: "Class 8",
    class_position: 1,
    total_marks: 98,
    created_at: new Date().toISOString(),
  },
  {
    id: "sample-4",
    certificate_name: "সাদিয়া রহমান",
    school_name: "আইডিয়াল স্কুল অ্যান্ড কলেজ",
    exam_name: "বার্ষিক পরীক্ষা ২০২৫",
    class_name: "Class 7",
    class_position: 3,
    total_marks: 89,
    created_at: new Date().toISOString(),
  },
  {
    id: "sample-5",
    certificate_name: "ফারহান কবির",
    school_name: "রাজউক উত্তরা মডেল কলেজ",
    exam_name: "প্রথম সাময়িক পরীক্ষা ২০২৫",
    class_name: "Class 6",
    class_position: 1,
    total_marks: 96,
    created_at: new Date().toISOString(),
  },
];

function GalleryPage() {
  const [rows, setRows] = useState<Row[]>([]);
  const [loading, setLoading] = useState(true);
  const [cls, setCls] = useState("All");
  const [q, setQ] = useState("");

  useEffect(() => {
    supabase
      .from("result_submissions")
      .select(
        "id,certificate_name,school_name,exam_name,class_name,class_position,total_marks,created_at",
      )
      .order("created_at", { ascending: false })
      .limit(300)
      .then(({ data }) => {
        if (data && data.length > 0) {
          setRows(data as Row[]);
        } else {
          setRows(MOCK_ROWS);
        }
        setLoading(false);
      })
      .catch(() => {
        setRows(MOCK_ROWS);
        setLoading(false);
      });
  }, []);

  const filtered = useMemo(() => {
    const term = q.trim().toLowerCase();
    return rows.filter((r) => {
      if (cls !== "All" && r.class_name !== cls) return false;
      if (!term) return true;
      return (
        r.certificate_name.toLowerCase().includes(term) ||
        r.school_name.toLowerCase().includes(term)
      );
    });
  }, [rows, cls, q]);

  return (
    <main className="min-h-screen bg-background">
      <SiteHeader />

      <section className="border-b border-border bg-surface-tinted">
        <div className="mx-auto max-w-5xl px-6 py-12 text-center">
          <h1 className="text-3xl leading-tight font-bold tracking-tight sm:text-4xl">
            Certificate Gallery
          </h1>
          <p className="bn mx-auto mt-3 max-w-2xl text-[0.9375rem] text-text-2">
            সব শিক্ষার্থীর তৈরি করা সার্টিফিকেট এক জায়গায়। শ্রেণি অনুযায়ী ফিল্টার করো, বা নাম /
            স্কুলের নাম দিয়ে খুঁজে দেখো।
          </p>
        </div>
      </section>

      <section className="mx-auto max-w-7xl px-6 py-8">
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center">
          <div className="flex flex-wrap gap-2">
            {CLASS_FILTERS.map((c) => (
              <button
                key={c}
                onClick={() => setCls(c)}
                className={`rounded-full border px-4 py-2 text-sm font-medium transition ${
                  cls === c
                    ? "border-primary bg-primary-container text-on-primary-container"
                    : "border-border bg-card text-text-2 hover:border-primary"
                }`}
              >
                {c}
              </button>
            ))}
          </div>
          <input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search by student or school name"
            className="w-full rounded-xl border border-border bg-card px-4 py-3 text-[0.9375rem] outline-none transition placeholder:text-muted-foreground focus:border-primary focus:ring-2 focus:ring-primary/20 sm:ml-auto sm:max-w-xs"
          />
        </div>

        {loading ? (
          <p className="bn py-16 text-center text-text-3">লোড হচ্ছে...</p>
        ) : filtered.length === 0 ? (
          <p className="bn py-16 text-center text-text-3">কোনো সার্টিফিকেট পাওয়া যায়নি।</p>
        ) : (
          <div className="mt-8 grid gap-5 grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6">
            {filtered.map((r) => (
              <Link
                key={r.id}
                to="/certificate"
                search={{
                  name: r.certificate_name,
                  school: r.school_name,
                  exam: r.exam_name,
                  position: r.class_position,
                  marks: String(r.total_marks),
                  cls: r.class_name ?? undefined,
                  view: 1,
                  fcls: cls,
                  fq: q,
                }}
                className="group overflow-hidden rounded-2xl border border-border bg-card transition hover:border-primary"
              >
                <div className="overflow-hidden border-b border-border">
                  <Certificate
                    data={{
                      studentName: r.certificate_name,
                      schoolName: r.school_name,
                      examName: r.exam_name,
                      position: r.class_position,
                      totalMarks: String(r.total_marks),
                      className: r.class_name ?? undefined,
                    }}
                  />
                </div>
                <div className="p-3">
                  <p className="truncate text-sm font-semibold">{r.certificate_name}</p>
                  <p className="mt-0.5 truncate text-xs text-text-3">{r.school_name}</p>
                  <p className="mt-1.5 truncate text-[11px] font-medium text-green-link">
                    {r.class_name ?? "—"} · {r.exam_name} · Position {r.class_position}
                  </p>
                </div>
              </Link>
            ))}
          </div>
        )}
      </section>
    </main>
  );
}
